result=js(r'''(async()=>{
const T=await import('three'),s=await import('./js/world/shop-slice.js'),kit=await import('./js/world/building-kit.js'),{townhouseMaterials}=await import('./js/world/building-slice-materials.js');const check=(v,m)=>{if(!v)throw Error(m)},plots=window.__cityAudit.plots,ids=[...s.SHOP_LOT_IDS,...s.SHOP_INTEGRATION_IDS],selected=ids.map(id=>plots.find(p=>p.id===id));
check(typeof s.heroShopRecipe==='function','hero composition recipes exist');const compositions=new Set,shapes=new Set,materials=new Set,maps=new Set;let triangles=0;
for(const p of selected){const recipe=s.heroShopRecipe(p,plots);compositions.add(recipe.composition);check(JSON.stringify(recipe)===JSON.stringify(s.heroShopRecipe(p,plots.slice().reverse())),'stable recipe');const g=s.createShopSlice(p,plots,recipe);shapes.add(JSON.stringify(g.userData.openings.filter(o=>o.face==='front').map(({u,y,w,h,type})=>[u,y,w,h,type])));check(g.children.length===3,'three policy buckets');for(const [k,m]of g.children.entries()){check(m.castShadow===(k===0),'shadow policy');materials.add(m.material);Object.values(m.material).forEach(v=>{if(v?.isTexture)maps.add(v)});const a=m.geometry.attributes;triangles+=a.position.count/3;for(const key of ['normal','uv','aSurface','color'])check(a[key].count===a.position.count,'merge attributes');for(let i=0;i<a.position.count;i++)check(Math.abs(a.position.getX(i))<=p.width/2+.001&&Math.abs(a.position.getZ(i))<=p.depth/2+.001&&a.position.getY(i)>=-.001&&a.position.getY(i)<=p.height+.001,'envelope');m.geometry.dispose();}}
check(compositions.size===4&&shapes.size>=4,'four architectural compositions, not color clones');check(materials.size===2&&maps.size===4&&triangles<=16000,'shared resources/local geometry budget');
const city=kit.createCityBuildings(plots);let meshes=0,mergedTriangles=0;for(const name of ['hero-shopfronts','hero-final-frontages'])city.getObjectByName(name).traverse(m=>{if(m.isMesh){meshes++;mergedTriangles+=m.geometry.attributes.position.count/3;}});check(meshes===12&&mergedTriangles===triangles,'existing four batches apply the exact local recipes');city.userData.dispose();return {pass:true,ids,compositions:[...compositions],renderables:meshes,triangles,materials:materials.size,maps:maps.size};})()''')
